import symtable, glob, builtins, ast
for p in glob.glob('/app/tally/reports/**/*.py', recursive=True):
    src = open(p, encoding='utf-8').read()
    top = symtable.symtable(src, p, 'exec')
    defined = {s.get_name() for s in top.get_symbols() if s.is_assigned() or s.is_imported() or s.is_namespace()}
    unused_imports = {s.get_name() for s in top.get_symbols() if s.is_imported() and not s.is_referenced()}
    def walk(t):
        for s in t.get_symbols():
            if (s.is_global() or (t is top and s.is_referenced())) and s.is_referenced():
                n = s.get_name()
                if n not in defined and not hasattr(builtins, n) and n not in ('__file__', '__name__'):
                    print('UNDEFINED', p, n)
        for c in t.get_children():
            walk(c)
    walk(top)
    # annotation names (strings under future import)
    tree = ast.parse(src)
    ann = set()
    for n in ast.walk(tree):
        anns = []
        if isinstance(n, ast.FunctionDef):
            anns += [a.annotation for a in n.args.args + n.args.kwonlyargs if a.annotation] + ([n.returns] if n.returns else [])
        if isinstance(n, ast.AnnAssign):
            anns.append(n.annotation)
        for a in anns:
            for x in ast.walk(a):
                if isinstance(x, ast.Name):
                    ann.add(x.id)
    for n in ann:
        if n not in defined and not hasattr(builtins, n) and n != 'annotations':
            print('UNDEFINED-ANN', p, n)
    ui = unused_imports - ann - {'annotations'}
    if ui:
        print('unused imports', p.replace('/app/tally/reports/', ''), sorted(ui))
EOF
